let commissionAck=false;
function commissionDialog(form:HTMLFormElement,then?:()=>void){let d=document.querySelector<HTMLDialogElement>('#commission-dialog');if(!d){d=document.createElement('dialog');d.id='commission-dialog';document.body.append(d);}const dlg=d;dlg.setAttribute('aria-labelledby','commission-title');dlg.innerHTML=`<div class="modal-head"><h2 id="commission-title">${t('cw_title')}</h2></div><div class="notice warn" role="alert"><p>${t('cw_intro')}</p><ol>${['cw_1','cw_2','cw_3','cw_4'].map(k=>`<li>${t(k)}</li>`).join('')}</ol></div><div class="modal-actions" style="display:flex;gap:10px;flex-wrap:wrap"><button type="button" id="commission-confirm">${t('cw_confirm')}</button><button type="button" class="secondary" id="commission-back">${t('cw_back')}</button></div>`;
 const back=()=>{commissionAck=false;dlg.close();const r=form.querySelector<HTMLInputElement>('[name=workSystem][value=commission]');if(r){r.checked=false;r.focus();}};
 dlg.querySelector<HTMLButtonElement>('#commission-confirm')!.onclick=()=>{commissionAck=true;dlg.close();then?.();};dlg.querySelector<HTMLButtonElement>('#commission-back')!.onclick=back;dlg.oncancel=e=>{e.preventDefault();back();};
 dlg.showModal();dlg.querySelector<HTMLButtonElement>('#commission-back')!.focus();}
