function wcForm(){return !custom&&!ibanForm()&&!leaveForm();}
function deviceKey(){return 'gate-wc-device:'+token;}
function deviceRecord():{iqama:string;editToken:string}|null{try{const raw=localStorage.getItem(deviceKey());if(!raw)return null;const d=JSON.parse(raw);return typeof d?.iqama==='string'&&/^[0-9]{10}$/.test(d.iqama)?{iqama:d.iqama,editToken:typeof d.editToken==='string'?d.editToken:''}:null;}catch{return null;}}
function saveDevice(iqama:string,tokenValue:string){if(!wcForm())return;try{localStorage.setItem(deviceKey(),JSON.stringify({iqama,editToken:tokenValue,at:new Date().toISOString()}));}catch{}}
function prefillDevice(form:HTMLFormElement){const dv=deviceRecord();if(!dv||editMode)return;const el=form.elements.namedItem('iqama') as HTMLInputElement|null;if(!el||el.value)return;el.value=dv.iqama;el.dispatchEvent(new Event('input',{bubbles:true}));}
function bindCommission(form:HTMLFormElement){form.querySelectorAll<HTMLInputElement>('[name=workSystem]').forEach(r=>r.addEventListener('change',()=>{if(r.value==='commission'&&r.checked)commissionDialog(form);else commissionAck=false;}));}
